import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const currentFileName = fileURLToPath(import.meta.url);
const currentDirName = path.dirname(currentFileName);

const parsersDir = path.join(currentDirName, '../parsers');
const outputFile = path.join(currentDirName, '../parsers/index.js');

const files = fs.readdirSync(parsersDir)
  .filter(file => file.endsWith('.js') && !file.startsWith('index'))
  .map(file => file.replace('.js', ''));

const indexContent = `
// Generated by generate-parser-index.js
export const parserList = ${JSON.stringify(files)};
`;

fs.writeFileSync(outputFile, indexContent);
console.log(`Generated parser index with ${files.length} parsers`); 
